package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Native router connection profile screen; password stays in Keystore. */
public final class RouterActivity extends Activity { private LinearLayout page;private EditText name,host,port,user,pass;private CheckBox tls;private TextView status;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle b){super.onCreate(b);build();} private void build(){page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(20,20,20,32);page.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);page.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(page);setContentView(s); UiTheme.apply(this);page.addView(txt("الراوترات والاتصالات",24));android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);name=field("اسم الملف",p.getString("router_name","الراوتر الحالي"));host=field("IP أو DNS",p.getString("host",""));port=field("منفذ API",p.getString("port","8728"));user=field("اسم المستخدم",p.getString("user","admin"));String pw="";try{pw=new SecureConnectionStore(this).get();}catch(Exception ignored){}pass=field("كلمة المرور",pw);pass.setInputType(0x81);tls=new CheckBox(this);tls.setText("TLS بشهادة موثوقة");tls.setChecked(p.getBoolean("tls",false));page.addView(tls);button("حفظ الملف المشفر",this::save);button("اختبار الاتصال",this::test);status=txt("لم يتم الاختبار",14);page.addView(status);}
 private void save(){try{getSharedPreferences("router_connection",MODE_PRIVATE).edit().putString("router_name",name.getText().toString().trim()).putString("host",host.getText().toString().trim()).putString("port",port.getText().toString().trim()).putString("user",user.getText().toString().trim()).putBoolean("tls",tls.isChecked()).commit();new SecureConnectionStore(this).put(pass.getText().toString());status.setText("تم حفظ بيانات الاتصال بأمان");}catch(Exception e){status.setText("تعذر الحفظ عبر Keystore");}}
 private void test(){save();status.setText("جاري اختبار الاتصال...");worker.execute(()->{try{int p=Integer.parseInt(port.getText().toString());try(RouterService r=new RouterService(host.getText().toString().trim(),p,tls.isChecked())){r.login(user.getText().toString().trim(),pass.getText().toString());r.execute("/system/resource/print","=.proplist=version,board-name");runOnUiThread(()->status.setText("تم الاتصال وقراءة معلومات الراوتر"));}}catch(Exception e){runOnUiThread(()->status.setText("فشل الاتصال: "+(e.getMessage()==null?"خطأ":e.getMessage())));}});}
 private EditText field(String h,String v){EditText e=new EditText(this);e.setHint(h);e.setText(v);e.setSingleLine(true);e.setTextSize(16);page.addView(e);return e;}private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(23,103,177)));page.addView(b);b.setOnClickListener(v->r.run());}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
